import string

M = 26
ALPHABET = string.ascii_lowercase


def _validate(a):
    if math_gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def _math_gcd(a, b):
    while b:
        a, b = b, a % b
    return a


math_gcd = _math_gcd


def _modular_inverse(a):
    a %= M
    for x in range(M):
        if (a * x) % M == 1:
            return x
    raise ValueError("a and m must be coprime.")


def encode(plain_text, a, b):
    _validate(a)
    chars = []
    for ch in plain_text.lower():
        if ch in ALPHABET:
            i = ALPHABET.index(ch)
            chars.append(ALPHABET[(a * i + b) % M])
        elif ch.isdigit():
            chars.append(ch)
    blocks = ["".join(chars[i : i + 5]) for i in range(0, len(chars), 5)]
    return " ".join(blocks)


def decode(ciphered_text, a, b):
    _validate(a)
    a_inv = _modular_inverse(a)
    chars = []
    for ch in ciphered_text.lower():
        if ch in ALPHABET:
            y = ALPHABET.index(ch)
            chars.append(ALPHABET[(a_inv * (y - b)) % M])
        elif ch.isdigit():
            chars.append(ch)
    return "".join(chars)

